ACTION: {"tool": "file-write", "args": {"path": "content/system/blocks/agents/code-reviewer/code-reviewer.agent.block.json", "content": "{
  "id": "code-reviewer",
  "name": "Code Reviewer",
  "blockType": "agent",
  "version": "1.0.0",
  "isAtomic": true,
  "description": "Reviews code for quality, bugs, security issues, and best practices. Provides structured feedback with actionable suggestions.",
  "contract": "code-reviewer",
  "capabilities": [
    "conversation",
    "structured-output",
    "tool-calling"
  ],
  "inputs": [
    { "id": "code", "type": "string", "required": true, "description": "The source code to review." },
    { "id": "language", "type": "string", "required": false, "description": "Programming language of the code (e.g. TypeScript, Python)." },
    { "id": "context", "type": "string", "required": false, "description": "Additional context about the code or review focus areas." }
  ],
  "outputs": [
    { "id": "review", "type": "string", "description": "Structured code review with findings and suggestions." },
    { "id": "issues", "type": "array", "description": "List of identified issues with severity and location." },
    { "id": "summary", "type": "string", "description": "High-level summary of the code quality and key findings." }
  ],
  "config": {
    "model": "claude-sonnet-4-6",
    "maxIterations": 15,
    "wallClockTimeoutSeconds": 600,
    "systemPromptFile": "system-prompt.md",
    "context": {
      "strategy": "sliding-window",
      "maxTokens": 8192,
      "keepSystemPrompt": true,
      "keepLastN": 15
    },
    "nodes": [
      {
        "id": "init",
        "type": "set-variable",
        "variable": "_agentDone",
        "value": "false"
      },
      {
        "id": "agent-while",
        "type": "while",
        "condition": "{{_agentDone}} != true",
        "maxIterations": "{{maxIterations}}",
        "nodes": [
          {
            "id": "read-conversation",
            "blockRef": "conversation-read",
            "inputs": { "conversationId": "{{_conversationId}}" }
          },
          {
            "id": "llm-call",
            "blockRef": "inference",
            "config": { "model": "claude-sonnet-4-6", "maxTokens": 4096, "temperature": 0 },
            "inputs": { "messages": "{{_nodeResult_read-conversation.messages}}" }
          },
          {
            "id": "append-assistant",
            "blockRef": "conversation-append",
            "inputs": {
              "conversationId": "{{_conversationId}}",
              "role": "assistant",
              "content": "{{_nodeResult_llm-call.content}}"
            }
          },
          {
            "id": "parse-response",
            "blockRef": "response-parser",
            "inputs": { "rawResponse": "{{_nodeResult_llm-call.content}}" }
          },
          {
            "id": "route-response",
            "type": "conditional",
            "condition": "{{_nodeResult_parse-response.type}}",
            "branches": {
              "tool-call": {
                "nodes": [
                  {
                    "id": "dispatch-tool",
                    "blockRef": "tool-dispatcher",
                    "inputs": {
                      "toolId": "{{_nodeResult_parse-response.toolId}}",
                      "args": "{{_nodeResult_parse-response.args}}"
                    }
                  },
                  {
                    "id": "append-tool-result",
                    "blockRef": "conversation-append",
                    "inputs": {
                      "conversationId": "{{_conversationId}}",
                      "role": "user",
                      "content": "[Tool result for {{_nodeResult_parse-response.toolId}}]:\n{{_nodeResult_dispatch-tool.result}}"
                    }
                  }
                ]
              },
              "step-complete": {
                "nodes": [
                  { "id": "set-done", "type": "set-variable", "variable": "_agentDone", "value": "true" },
                  { "id": "set-result", "type": "set-variable", "variable": "_agentResult", "value": "{{_nodeResult_parse-response.summary}}" }
                ]
              },
              "text": {
                "nodes": [
                  { "id": "set-text-result", "type": "set-variable", "variable": "_agentResult", "value": "{{_nodeResult_parse-response.text}}" },
                  { "id": "set-text-done", "type": "set-variable", "variable": "_agentDone", "value": "true" }
                ]
              },
              "retry": {
                "nodes": [
                  {
                    "id": "nudge-agent",
                    "blockRef": "conversation-append",
                    "inputs": {
                      "conversationId": "{{_conversationId}}",
                      "role": "user",
                      "content": "Your last response was empty or malformed. Respond with a JSON tool call. If done, call step-complete."
                    }
                  }
                ]
              }
            }
          }
        ]
      }
    ]
  },
  "metadata": {
    "category": "development",
    "designation": "agent",
    "tags": ["code-review", "quality", "security", "best-practices"],
    "tier": 2
  }
}
"}}

